#!/usr/bin/env bash
set -euo pipefail
echo "🐻 Installing Kodiak Devnet platform engine..."
if [ ! -d "web" ]; then echo "Error: run this from /workspaces/Kodiak."; exit 1; fi
cd web
npm install @raydium-io/raydium-sdk-v2@0.2.42-alpha bn.js
npm install -D @types/bn.js
cd ..
mkdir -p "$(dirname 'web/src/lib/raydium/devnet.ts')"
echo '' | base64 -d > 'web/src/lib/raydium/devnet.ts'
mkdir -p "$(dirname 'web/src/app/api/raydium/devnet-cpmm-config/route.ts')"
echo '' | base64 -d > 'web/src/app/api/raydium/devnet-cpmm-config/route.ts'
mkdir -p "$(dirname 'web/src/app/platform-setup/page.tsx')"
echo '' | base64 -d > 'web/src/app/platform-setup/page.tsx'
python - <<'PY'
from pathlib import Path
path = Path("web/src/app/dashboard/page.tsx")
text = path.read_text()
needle = '        <div className="mt-10">\n          <WalletSummary />\n        </div>\n'
replacement = needle + '\n        <div className="mt-6 flex justify-end">\n          <Link href="/platform-setup" className="rounded-2xl bg-gradient-to-r from-emerald-400 to-amber-300 px-5 py-3 font-black text-black">\n            Set up Kodiak Devnet platform\n          </Link>\n        </div>\n'
if "/platform-setup" not in text:
    if needle not in text:
        raise SystemExit("Dashboard layout was not recognized.")
    path.write_text(text.replace(needle, replacement))
PY
cd web
npm run lint
npm run build
cd ..
git add .
git commit -m "add Devnet LaunchLab platform setup engine" || true
echo ""
echo "✅ Kodiak Devnet platform engine installed."
echo "Refresh Kodiak, open Dashboard, then tap Set up Kodiak Devnet platform."
